-- oracle: pub400
SELECT SPECIFIC_SCHEMA, SPECIFIC_NAME, ORDINAL_POSITION, PARAMETER_MODE, PARAMETER_NAME, DATA_TYPE, CHARACTER_MAXIMUM_LENGTH, NUMERIC_PRECISION FROM QSYS2.SYSPARMS WHERE (SPECIFIC_SCHEMA = 'QSYS' AND SPECIFIC_NAME LIKE 'QQQDBVE%') OR (SPECIFIC_SCHEMA = 'QSYS2' AND SPECIFIC_NAME IN (SELECT SPECIFIC_NAME FROM QSYS2.SYSROUTINES WHERE ROUTINE_SCHEMA='QSYS2' AND ROUTINE_NAME IN ('DUMP_PLAN_CACHE','CLEAR_PLAN_CACHE','CHANGE_PLAN_CACHE_SIZE','DUMP_PLAN_CACHE_TOPN','DUMP_PLAN_CACHE_PROPERTIES','COLUMN_STATISTICS'))) ORDER BY 1, 2, 3;
SELECT ROUTINE_SCHEMA, ROUTINE_NAME, SPECIFIC_NAME, RESULT_SETS, IN_PARMS, OUT_PARMS, SQL_DATA_ACCESS, ROUTINE_BODY, LONG_COMMENT FROM QSYS2.SYSROUTINES WHERE (ROUTINE_SCHEMA='QSYS' AND ROUTINE_NAME='QQQDBVE') OR (ROUTINE_SCHEMA='QSYS2' AND ROUTINE_NAME IN ('DUMP_PLAN_CACHE','CLEAR_PLAN_CACHE','CHANGE_PLAN_CACHE_SIZE','COLUMN_STATISTICS'));
SELECT COLUMN_NAME, ORDINAL_POSITION, DATA_TYPE, LENGTH, NUMERIC_SCALE, IS_NULLABLE FROM QSYS2.SYSCOLUMNS WHERE TABLE_SCHEMA = 'QSYS2' AND TABLE_NAME = 'SYSCOLUMNSTAT' AND ORDINAL_POSITION > 45 ORDER BY 2;
SELECT COUNT(*) FROM QSYS2.SYSCOLUMNSTAT WHERE TABLE_SCHEMA = 'QSYS2';
SELECT TABLE_SCHEMA, TABLE_NAME, COLUMN_NAME, NUMBER_DISTINCT_VALUES, HIGH2KEY, LOW2KEY, AVERAGE_COLUMN_LENGTH, MAXIMUM_COLUMN_LENGTH, NUMBER_NULLS, NUMBER_HISTOGRAM_RANGES, NUMBER_MOST_FREQUENT_VALUES, STATISTICS_NAME, STATISTIC_CREATOR, AGING_MODE, AGING_STATUS, BLOCK_OPTION, CURRENT_ROWS, STATISTICS_ROWS, NUMBER_COLUMN_NAMES, TABLE_PARTITION, PARTITION_TYPE FROM QSYS2.SYSCOLUMNSTAT FETCH FIRST 5 ROWS ONLY;
SELECT * FROM TABLE(QSYS2.COLUMN_STATISTICS('QSYS2', 'SYSTABLES')) X FETCH FIRST 2 ROWS ONLY;
